-- RP World Maps package 06: characters DB stale instance-state cleanup (apply).
-- Generated by tools/character-openworld-migrate/generate_sql.py.
-- Source: tools/map-openworld-hotfix/golden/inventory.json (539 target maps).
-- Explicitly excluded by the frozen inventory: PvP, Arena, Housing map 2783 and all non-target maps.
-- Run against the `characters` database with worldserver stopped and a verified DB backup.
SET NAMES utf8mb4;


SET @rps_add_flags4 = (
  SELECT IF(
    COUNT(*) = 0,
    'ALTER TABLE `characters` ADD COLUMN `flags4` INT UNSIGNED NOT NULL DEFAULT 0 AFTER `timerunningSeasonId`',
    'SELECT 1'
  )
  FROM `information_schema`.`COLUMNS`
  WHERE `TABLE_SCHEMA` = DATABASE()
    AND `TABLE_NAME` = 'characters'
    AND `COLUMN_NAME` = 'flags4'
);
PREPARE rps_flags4_stmt FROM @rps_add_flags4;
EXECUTE rps_flags4_stmt;
DEALLOCATE PREPARE rps_flags4_stmt;

DROP TEMPORARY TABLE IF EXISTS `rps_openworld_target_map_20260808`;
CREATE TEMPORARY TABLE `rps_openworld_target_map_20260808` (
  `map_id` int unsigned NOT NULL,
  PRIMARY KEY (`map_id`)
) ENGINE=Memory;

SELECT 'target_map_count' AS `check`, COUNT(*) AS `actual`, 539 AS `expected`
FROM `rps_openworld_target_map_20260808`;

-- Archive tables retain a pre-image for operator audit after apply.
-- Recovery is from a verified characters DB backup, not from generated rollback SQL.
-- CREATE TABLE is DDL and commits in MySQL; all copied and mutated rows below are
-- protected by the following transaction.
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_character_instance_lock` LIKE `character_instance_lock`;
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_account_instance_times` LIKE `account_instance_times`;
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_respawn` LIKE `respawn`;
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_instance` LIKE `instance`;
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_characters` LIKE `characters`;
CREATE TABLE IF NOT EXISTS `rps_openworld_20260808_corpse` LIKE `corpse`;

START TRANSACTION;

-- Snapshot target instance IDs before deleting their target-map locks.
DROP TEMPORARY TABLE IF EXISTS `rps_openworld_target_instance_20260808`;
CREATE TEMPORARY TABLE `rps_openworld_target_instance_20260808` (
  `instance_id` int unsigned NOT NULL,
  PRIMARY KEY (`instance_id`)
) ENGINE=Memory;
SELECT DISTINCT cil.`instanceId`
FROM `character_instance_lock` AS cil
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = cil.`mapId`
WHERE cil.`instanceId` IS NOT NULL AND cil.`instanceId` <> 0;

SELECT DISTINCT c.`instance_id`
FROM `characters` AS c
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = c.`map`
WHERE c.`instance_id` <> 0;

SELECT DISTINCT co.`instanceId`
FROM `corpse` AS co
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
WHERE co.`instanceId` <> 0;

SELECT DISTINCT r.`instanceId`
FROM `respawn` AS r
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = r.`mapId`
WHERE r.`instanceId` <> 0;

-- Only delete a parent when no non-target lock still refers to it.
DROP TEMPORARY TABLE IF EXISTS `rps_openworld_delete_instance_20260808`;
CREATE TEMPORARY TABLE `rps_openworld_delete_instance_20260808` (
  `instance_id` int unsigned NOT NULL,
  PRIMARY KEY (`instance_id`)
) ENGINE=Memory;
SELECT ti.`instance_id`
FROM `rps_openworld_target_instance_20260808` AS ti
JOIN `instance` AS i ON i.`instanceId` = ti.`instance_id`;

DELETE di
FROM `rps_openworld_delete_instance_20260808` AS di
JOIN `character_instance_lock` AS cil ON cil.`instanceId` = di.`instance_id`
LEFT JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = cil.`mapId`
WHERE tm.`map_id` IS NULL;

DELETE di
FROM `rps_openworld_delete_instance_20260808` AS di
JOIN `characters` AS c ON c.`instance_id` = di.`instance_id`
LEFT JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = c.`map`
WHERE tm.`map_id` IS NULL;

DELETE di
FROM `rps_openworld_delete_instance_20260808` AS di
JOIN `respawn` AS r ON r.`instanceId` = di.`instance_id`
LEFT JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = r.`mapId`
WHERE tm.`map_id` IS NULL;

DELETE di
FROM `rps_openworld_delete_instance_20260808` AS di
JOIN `corpse` AS co ON co.`instanceId` = di.`instance_id`
LEFT JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
WHERE tm.`map_id` IS NULL;

-- Account release times have no map column. Remove them only for a deleted
-- target parent or an already-orphaned target parent; preserve the value when
-- a non-target lock is the reason a shared parent remains.
DROP TEMPORARY TABLE IF EXISTS `rps_openworld_cleanup_account_instance_20260808`;
CREATE TEMPORARY TABLE `rps_openworld_cleanup_account_instance_20260808` (
  `instance_id` int unsigned NOT NULL,
  PRIMARY KEY (`instance_id`)
) ENGINE=Memory;
SELECT ti.`instance_id`
FROM `rps_openworld_target_instance_20260808` AS ti
LEFT JOIN `instance` AS i ON i.`instanceId` = ti.`instance_id`
LEFT JOIN `rps_openworld_delete_instance_20260808` AS di ON di.`instance_id` = ti.`instance_id`
WHERE i.`instanceId` IS NULL OR di.`instance_id` IS NOT NULL;

-- Backup complete source rows (including each table's primary key) before mutation.
SELECT cil.*
FROM `character_instance_lock` AS cil
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = cil.`mapId`;

SELECT ait.*
FROM `account_instance_times` AS ait
JOIN `rps_openworld_cleanup_account_instance_20260808` AS ti ON ti.`instance_id` = ait.`instanceId`;

SELECT r.*
FROM `respawn` AS r
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = r.`mapId`;

SELECT i.*
FROM `instance` AS i
JOIN `rps_openworld_delete_instance_20260808` AS di ON di.`instance_id` = i.`instanceId`;

SELECT c.*
FROM `characters` AS c
WHERE c.`map` IN (SELECT `map_id` FROM `rps_openworld_target_map_20260808`)
   OR (c.`health` = 0 AND EXISTS (
       SELECT 1
       FROM `corpse` AS co
       JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
       WHERE co.`guid` = c.`guid`
   ));

SELECT co.*
FROM `corpse` AS co
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`;

-- Delete children first. Account lock times and respawns are stale only where
-- their instance/map is in this target migration; non-target maps are untouched.
DELETE cil
FROM `character_instance_lock` AS cil
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = cil.`mapId`;

DELETE ait
FROM `account_instance_times` AS ait
JOIN `rps_openworld_cleanup_account_instance_20260808` AS ti ON ti.`instance_id` = ait.`instanceId`;

DELETE r
FROM `respawn` AS r
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = r.`mapId`;

-- Delete only now-unreferenced instance parents. A parent with a non-target
-- lock remains intact and is reported by the post-apply check queries.
DELETE i
FROM `instance` AS i
JOIN `rps_openworld_delete_instance_20260808` AS di ON di.`instance_id` = i.`instanceId`;

-- Target-map characters no longer carry an instance ID. 0x100 is
-- AT_LOGIN_RESURRECT (Player.h); it is ORed in only for affected dead players.
UPDATE `characters` AS c
SET c.`instance_id` = 0,
    c.`at_login` = CASE
      WHEN c.`health` = 0 THEN c.`at_login` | 0x100
      ELSE c.`at_login`
    END
WHERE c.`map` IN (SELECT `map_id` FROM `rps_openworld_target_map_20260808`);

UPDATE `characters` AS c
JOIN `corpse` AS co ON co.`guid` = c.`guid`
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
SET c.`instance_id` = 0,
    c.`at_login` = c.`at_login` | 0x100
WHERE c.`health` = 0;

-- Corpses stay in place, but become world-instance corpses. Their phase and
-- customization children remain valid because the corpse row is not deleted.
UPDATE `corpse` AS co
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
SET co.`instanceId` = 0;

COMMIT;

-- Post-apply target-scoped checks. Every `actual` must be 0, except the final
-- informational count of parents retained for still-existing non-target locks.
SELECT 'stale_character_instance_id' AS `check`, COUNT(*) AS `actual`
FROM `characters` AS c
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = c.`map`
WHERE c.`instance_id` <> 0;

SELECT 'target_character_instance_lock' AS `check`, COUNT(*) AS `actual`
FROM `character_instance_lock` AS cil
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = cil.`mapId`;

SELECT 'target_respawn' AS `check`, COUNT(*) AS `actual`
FROM `respawn` AS r
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = r.`mapId`;

SELECT 'target_corpse_instance_id' AS `check`, COUNT(*) AS `actual`
FROM `corpse` AS co
JOIN `rps_openworld_target_map_20260808` AS tm ON tm.`map_id` = co.`mapId`
WHERE co.`instanceId` <> 0;

SELECT 'deletable_parent_left' AS `check`, COUNT(*) AS `actual`
FROM `instance` AS i
JOIN `rps_openworld_delete_instance_20260808` AS di ON di.`instance_id` = i.`instanceId`;

SELECT 'retained_parent_with_non_target_lock' AS `check`, COUNT(*) AS `actual`
FROM `instance` AS i
JOIN `rps_openworld_target_instance_20260808` AS ti ON ti.`instance_id` = i.`instanceId`;
